flowDot:
digraph G {
  rankdir=TB; bgcolor="transparent"; nodesep=0.28; ranksep=0.55; newrank=true;
  node [fontname="Helvetica", fontsize=12, style="rounded,filled", penwidth=2];
  edge [fontname="Helvetica", fontsize=11, color="#6B7280"];
  START [label="Build messages\n(the user's request)", shape=box, style="rounded,filled", fillcolor="#DBEAFE", color="#0066CC"];
  SEND [label="Send request\nmessages.create(messages, tools)", shape=box, style="rounded,filled", fillcolor="#DBEAFE", color="#0066CC"];
  INSPECT [label="Read\nstop_reason", shape=diamond, style="rounded,filled", fillcolor="#EDE9FE", color="#7C3AED"];
  EXEC [label="⭐ tool_use\n→ run every tool", shape=box, style="rounded,filled", fillcolor="#DBEAFE", color="#0066CC"];
  APPEND [label="Append assistant turn +\none user message of tool_results", shape=box, style="rounded,filled", fillcolor="#DBEAFE", color="#0066CC"];
  DONE [label="⭐ end_turn\n→ the final answer", shape=box, style="rounded,filled", fillcolor="#D1FAE5", color="#059669"];
  TRUNC [label="max_tokens (truncated)\n→ raise max_tokens", shape=box, style="rounded,filled", fillcolor="#FEF3C7", color="#D97706"];
  REFUSAL [label="refusal (HTTP 200)\n→ retry on a DIFFERENT model", shape=box, style="rounded,filled", fillcolor="#FEF3C7", color="#D97706"];
  PAUSE [label="pause_turn\n→ send the response back as-is", shape=box, style="rounded,filled", fillcolor="#FEF3C7", color="#D97706"];
  HANDLE [label="stop_sequence / anything else\n→ handle explicitly", shape=box, style="rounded,filled", fillcolor="#E5E7EB", color="#6B7280"];
  LOOP [label="↺ next turn", shape=box, style="rounded,filled", fillcolor="#DBEAFE", color="#0066CC"];
  BACKSTOP [label="turn > MAX_TURNS\n→ fail loudly (SDK: error_max_turns)", shape=box, style="rounded,filled", fillcolor="#E5E7EB", color="#6B7280"];
  ABANDON [label="✗ leave the loop while the model\nstill wants to continue", shape=box, style="rounded,filled,dashed", fillcolor="#FFFFFF", color="#DC2626"];
  NOMODEL [label="✗ developer hard-codes the\ntool order (no model call)", shape=box, style="rounded,filled,dashed", fillcolor="#FFFFFF", color="#DC2626"];
  START -> SEND -> INSPECT;
  INSPECT -> EXEC;
  INSPECT -> TRUNC;
  INSPECT -> REFUSAL;
  INSPECT -> PAUSE;
  INSPECT -> DONE;
