  { rank=same; EXEC; TRUNC; REFUSAL; PAUSE; DONE; HANDLE; }
  EXEC -> APPEND -> LOOP;
  TRUNC -> LOOP;
  REFUSAL -> LOOP;
  PAUSE -> LOOP;
